def tf_idf(docs):
    # docs: 토큰 리스트들의 리스트
    N = len(docs)
    df = {}
    for d in docs:
        for t in set(d):
            df[t] = df.get(t, 0) + 1  # 단어가 나온 문서 수
    vectors = []
    for d in docs:
        vec = {}
        for t in set(d):
            tf = d.count(t) / len(d)  # 문서 내 상대 빈도
            idf = log(N / df[t])  # 모든 문서에 나오면 0
            vec[t] = tf * idf
        vectors.append(vec)
    return vectors
